/**
 * 命令行字符串 ↔ 参数数组。
 * 「一整行命令」的配置入口（`--cmd`、`SPARC3D_CODEX_CMD`）必须能表达带空格的路径，
 * 用 `split(/\s+/)` 会把 `/Users/a b/cli.ts` 拆成两个参数。
 *
 * 语法是 POSIX shell 的一个子集：只处理引用与转义，不做变量展开 / 通配 / 重定向 / 管道，
 * 也不经过 shell（`spawn(bin, args)` 而非 `shell: true`），命令里的元字符不会被再解释一次。
 *   - 空白分隔参数，连续空白等价于一个
 *   - `'...'` 内全部字面量：Windows 路径的反斜杠不会被吃掉，首选这种引法
 *   - `"..."` 内 `\x` 取 x 的字面量，其余字面量
 *   - 引号外 `\x` 取 x 的字面量
 */

const WHITESPACE = /\s/;
const NEEDS_QUOTING = /[\s"'\\]/;

/** 拆分一行命令为参数数组；引号未闭合时抛错，避免把半个路径当成参数悄悄跑起来。 */
export function tokenizeCommandLine(input: string): string[] {
  const tokens: string[] = [];
  let current = '';
  // 单独记一个「本参数已开始」标记，才能区分显式的空参数 `''` 与参数之间的空白
  let started = false;
  let quote: '"' | "'" | null = null;

  for (let index = 0; index < input.length; index += 1) {
    const char = input[index]!;
    if (quote === "'") {
      if (char === "'") quote = null;
      else current += char;
      continue;
    }
    if (char === '\\') {
      const next = input[index + 1];
      if (next === undefined) throw new Error(`命令行以孤立的反斜杠结尾：${input}`);
      current += next;
      started = true;
      index += 1;
      continue;
    }
    if (quote === '"') {
      if (char === '"') quote = null;
      else current += char;
      continue;
    }
    if (char === '"' || char === "'") {
      quote = char;
      started = true;
      continue;
    }
    if (WHITESPACE.test(char)) {
      if (started) {
        tokens.push(current);
        current = '';
        started = false;
      }
      continue;
    }
    current += char;
    started = true;
  }

  if (quote) throw new Error(`命令行引号未闭合（${quote}）：${input}`);
  if (started) tokens.push(current);
  return tokens;
}

/** 参数数组 → 命令行字符串，满足 `tokenizeCommandLine(formatCommandLine(args))` 等于 `args`。 */
export function formatCommandLine(args: readonly string[]): string {
  return args.map(quoteCommandArg).join(' ');
}

/** 单个参数的引用形式：不含特殊字符时原样返回，方便人读。 */
export function quoteCommandArg(arg: string): string {
  if (arg.length > 0 && !NEEDS_QUOTING.test(arg)) return arg;
  // 优先单引号：Windows 路径里的反斜杠在单引号内是字面量，不必再转义一遍
  if (!arg.includes("'")) return `'${arg}'`;
  return `"${arg.replace(/(["\\])/g, '\\$1')}"`;
}
